<style>
.fp [hidden]{display:none!important}
.fp{--fp-green:#1a4d3a;max-width:1600px;margin:auto;color:#25372e}.fp h1{font-size:27px;margin:0 0 6px}.fp h2{font-size:19px;margin:0 0 16px}.fp h3{font-size:16px;margin:0 0 12px}.fp p{line-height:1.6}.fp-muted{color:#687b70;font-size:13px}.fp-head,.fp-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.fp-head{margin-bottom:22px}.fp-card{background:#fff;border:1px solid #dce6df;border-radius:14px;padding:22px;margin:18px 0;box-shadow:0 4px 18px #173f2b05}.fp-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.fp label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:600}.fp input,.fp select,.fp textarea{box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid #ccd9d0;border-radius:8px;background:white;color:#25372e;font:inherit}.fp input[type=checkbox]{width:17px;height:17px}.fp .fp-check{flex-direction:row;align-items:center;font-weight:400}.fp fieldset{border:0;padding:0;margin:18px 0}.fp legend{font-weight:700;margin-bottom:12px}.fp-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #cddbd2;background:white;color:var(--fp-green);border-radius:8px;padding:10px 15px;font:inherit;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.fp-btn.primary{background:var(--fp-green);color:white;border-color:var(--fp-green)}.fp-btn.danger{color:#a22d2d}.fp-note{padding:13px 16px;background:#eef5f0;border-radius:8px;font-size:13px;margin:14px 0}.fp-warning{background:#fff8e8;color:#805317}.fp-error{background:#fff0ee;color:#9b2828}.fp-scroll{overflow-x:auto}.fp table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}.fp th,.fp td{text-align:left;padding:12px;border-bottom:1px solid #e3ebe6}.fp th{background:#f3f7f4;color:#4b6455;font-weight:600}.fp td.number{text-align:right;font-variant-numeric:tabular-nums}.fp tr.total-row{font-weight:700;background:#edf5ef}.fp .negative{color:#b23a32}.fp-badge{display:inline-block;background:#edf5ef;color:#285840;border-radius:20px;padding:4px 10px;font-size:12px}.fp-badge.warn{background:#fff3d8;color:#805317}.fp-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.fp-tabs a{padding:9px 16px;border:1px solid #d5e0d8;border-radius:20px;color:#476151;text-decoration:none;font-size:13px}.fp-tabs a.active{background:#1a4d3a;color:#fff}.fp summary{cursor:pointer;font-weight:600}.fp .fp-kpi{font-size:25px;font-weight:700;margin-top:10px}.fp small{font-weight:400;line-height:1.5}.fp .fp-wide{grid-column:1/-1}.fp details+details{margin-top:10px}.fp .fp-line-note{white-space:normal;min-width:180px;max-width:350px;font-size:12px;color:#7b6332}.fp .fp-check-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;max-height:220px;overflow:auto;margin:12px 0}.fp .fp-metric-title{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#698070}@media(max-width:650px){.fp-card{padding:15px}.fp h1{font-size:23px}.fp-grid{grid-template-columns:1fr}}
</style>
<style>
.fp-hint{display:inline-flex;vertical-align:middle}.fp-hint-trigger{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:help;text-align:inherit}.fp-value-hint{text-decoration:underline;text-decoration-style:dotted;text-decoration-color:#a7baae;text-underline-offset:4px;white-space:nowrap}.fp-info{display:inline-flex;align-items:center;justify-content:center;width:19px;height:19px;border:1px solid #b8cdbf;border-radius:50%;font-size:11px;font-weight:700;color:#37644c;margin-left:5px}.fp-hint-trigger:focus-visible,.fp-chart-panel g:focus-visible{outline:2px solid #337d5a;outline-offset:3px}.fp-tooltip{position:fixed;inset:auto;margin:0;box-sizing:border-box;width:max-content;max-width:min(430px,calc(100vw - 24px));max-height:min(420px,calc(100dvh - 32px));overflow:auto;padding:15px 18px;border:1px solid #cbdcd0;border-radius:10px;background:#fff;color:#25372e;box-shadow:0 10px 35px #183d302b;font:13px/1.6 system-ui,sans-serif;text-transform:none;letter-spacing:normal;white-space:normal;text-align:left}.fp-tooltip strong{display:block;margin-bottom:7px;color:#194731}.fp-tooltip-text{display:block;white-space:pre-wrap}.fp-tooltip ul{padding-left:18px;margin:8px 0 0}.fp-tooltip li{margin:5px 0;white-space:pre-wrap;overflow-wrap:anywhere}.fp .fp-line-note{white-space:nowrap;min-width:90px;max-width:none}.fp-notes-badge{padding:5px 9px;background:#fff5dd;color:#7c5716;border-radius:12px;font-size:12px;white-space:nowrap}.fp-live-status{display:flex;gap:12px;align-items:center;font-size:12px;color:#537660;max-width:480px}.fp-refresh-error{color:#a33e2d}.fp-chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.fp-chart-panel{min-width:0;border:1px solid #e1e9e3;border-radius:10px;padding:16px 10px 2px}.fp-chart-panel h3{margin:0 8px 8px}.fp-chart-scroll{overflow-x:auto}.fp-chart-scroll svg{width:100%;display:block;max-height:310px}.fp-chart-axis{font:11px system-ui,sans-serif;fill:#63786b}.fp-chart-legend{display:flex;gap:20px;flex-wrap:wrap;margin:-5px 0 20px;font-size:12px;color:#526b5b}.fp-chart-legend span{display:inline-flex;align-items:center;gap:6px}.fp-chart-legend i{width:11px;height:11px;border-radius:3px}.fp-chart-total{font-size:22px;color:#194731}.fp-chart-total small{display:block;font-size:12px;color:#687b70;text-align:right}.fp-cost-chart>details{margin-top:18px}.fp-cost-chart .fp-head p{margin:0}.fp-cost-chart h2{margin-bottom:6px}@media(max-width:950px){.fp-chart-grid{grid-template-columns:1fr}.fp-live-status{flex-wrap:wrap}}
</style>
